import sys

def solve() -> None:
    input = sys.stdin.readline
    n_line = input()
    if not n_line:
        return
    N = int(n_line.strip())
    S = input().strip()
    n = len(S)

    # Consecutive '1's ending at each position
    left1 = [0] * n
    for i, ch in enumerate(S):
        if ch == '1':
            left1[i] = left1[i - 1] + 1 if i > 0 else 1
        else:
            left1[i] = 0

    # Consecutive '2's starting at each position
    right2 = [0] * n
    for i in range(n - 1, -1, -1):
        ch = S[i]
        if ch == '2':
            right2[i] = right2[i + 1] + 1 if i + 1 < n else 1
        else:
            right2[i] = 0

    max_len = 1  # at least one slash exists
    for i, ch in enumerate(S):
        if ch == '/':
            left_len = left1[i - 1] if i > 0 else 0
            right_len = right2[i + 1] if i + 1 < n else 0
            k = left_len if left_len < right_len else right_len
            curr_len = 2 * k + 1
            if curr_len > max_len:
                max_len = curr_len

    print(max_len)

if __name__ == "__main__":
    solve()
